    border-radius: 0 6px 6px 0;
  }}
  .finding strong {{
    color: var(--text);
  }}
  .finding p {{
    margin: 4px 0 0 0;
    color: var(--text-secondary);
    font-size: 14px;
  }}
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }}
  @media (max-width: 768px) {{
    .two-col {{ grid-template-columns: 1fr; }}
    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
    .container {{ padding: 16px 12px; }}
    .section {{ padding: 20px; }}
  }}
  .highlight {{ color: var(--accent); font-weight: 600; }}
  .neg {{ color: var(--negative); font-weight: 600; }}
  .pos {{ color: var(--positive); font-weight: 600; }}
</style>
</head>
<body>

<div class="report-header">
  <h1>Global Fuel Price Trends & Policy Impact Analysis</h1>
  <div class="subtitle">Comprehensive analysis of retail fuel prices across {n_countries} countries, examining Brent Crude benchmarks, taxation, subsidies, and regional economic conditions</div>
  <div class="meta">{date_range} &middot; {n_countries} Countries &middot; 7 Regions &middot; {n_weeks} Weekly Observations</div>
</div>

<div class="container">

<!-- ═══ SECTION 1: GLOBAL OVERVIEW ═══ -->
<div class="section">
  <h2>1. Global Fuel Price Overview</h2>
  <p>Summary statistics for retail fuel prices and Brent Crude across the full 2020–2026 period. All prices in USD per liter (Brent Crude in USD per barrel).</p>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="value">${overall_stats['petrol_usd_liter']['mean']}</div>
      <div class="label">Avg Petrol (USD/L)</div>
    </div>
    <div class="kpi-card">
      <div class="value">${overall_stats['diesel_usd_liter']['mean']}</div>
      <div class="label">Avg Diesel (USD/L)</div>
    </div>
    <div class="kpi-card">
      <div class="value">${overall_stats['lpg_usd_liter']['mean']}</div>
      <div class="label">Avg LPG (USD/L)</div>
    </div>
    <div class="kpi-card">
      <div class="value">${brent_overall['mean']}</div>
      <div class="label">Avg Brent Crude (USD/bbl)</div>
    </div>
  </div>

  <h3>Price Distribution Summary</h3>
