import pandas as pd
import numpy as np
from scipy import stats
import json
import os

# ─── Load Data ───
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['date'])
df['year'] = df['date'].dt.year

# ─── Compute all analysis data ───

# 1. GLOBAL OVERVIEW
overall_stats = {}
for fuel in ['petrol_usd_liter', 'diesel_usd_liter', 'lpg_usd_liter']:
    s = df[fuel]
    overall_stats[fuel] = {
        'mean': round(s.mean(), 3),
        'median': round(s.median(), 3),
        'std': round(s.std(), 3),
        'min': round(s.min(), 3),
        'max': round(s.max(), 3),
        'q25': round(s.quantile(0.25), 3),
        'q75': round(s.quantile(0.75), 3),
    }

brent_stats = df.groupby('date')['brent_crude_usd'].first()
brent_overall = {
    'mean': round(brent_stats.mean(), 2),
    'min': round(brent_stats.min(), 2),
    'max': round(brent_stats.max(), 2),
    'std': round(brent_stats.std(), 2),
}

n_countries = df['country'].nunique()
n_weeks = df['date'].nunique()
date_range = f"{df['date'].min().strftime('%B %Y')} – {df['date'].max().strftime('%B %Y')}"

# 2. TEMPORAL TRENDS & VOLATILITY
weekly_avg = df.groupby('date').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'brent_crude_usd': 'first',
}).reset_index()

weekly_avg['year'] = weekly_avg['date'].dt.year

# Yearly averages
yearly_avg = df.groupby('year').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'brent_crude_usd': 'mean',
}).reset_index()
yearly_avg = yearly_avg.round(3)

# Volatility (coefficient of variation) by year
yearly_volatility = df.groupby('year').agg({
    'petrol_usd_liter': lambda x: x.std() / x.mean(),
    'diesel_usd_liter': lambda x: x.std() / x.mean(),
    'lpg_usd_liter': lambda x: x.std() / x.mean(),
}).reset_index()
yearly_volatility.columns = ['year', 'petrol_cv', 'diesel_cv', 'lpg_cv']
yearly_volatility = yearly_volatility.round(4)

# Brent-to-Retail Correlation
corr_petrol = df['brent_crude_usd'].corr(df['petrol_usd_liter'])
corr_diesel = df['brent_crude_usd'].corr(df['diesel_usd_liter'])
corr_lpg = df['brent_crude_usd'].corr(df['lpg_usd_liter'])

# Pearson with p-values
r_petrol, p_petrol = stats.pearsonr(df['brent_crude_usd'].dropna(), df.loc[df['brent_crude_usd'].notna(), 'petrol_usd_liter'].dropna())
r_diesel, p_diesel = stats.pearsonr(df['brent_crude_usd'].dropna(), df.loc[df['brent_crude_usd'].notna(), 'diesel_usd_liter'].dropna())

# Key crisis periods
covid_period = df[(df['date'] >= '2020-03-01') & (df['date'] <= '2020-06-30')]
crisis_2022 = df[(df['date'] >= '2022-01-01') & (df['date'] <= '2022-12-31')]

covid_avg_petrol = round(covid_period['petrol_usd_liter'].mean(), 3)
covid_avg_brent = round(covid_period['brent_crude_usd'].mean(), 2)
crisis_avg_petrol = round(crisis_2022['petrol_usd_liter'].mean(), 3)
crisis_avg_brent = round(crisis_2022['brent_crude_usd'].mean(), 2)

# Pre-covid baseline (Jan-Feb 2020)
pre_covid = df[(df['date'] >= '2020-01-01') & (df['date'] <= '2020-02-29')]
pre_covid_petrol = round(pre_covid['petrol_usd_liter'].mean(), 3)
pre_covid_brent = round(pre_covid['brent_crude_usd'].mean(), 2)

covid_petrol_drop = round((1 - covid_avg_petrol / pre_covid_petrol) * 100, 1)
covid_brent_drop = round((1 - covid_avg_brent / pre_covid_brent) * 100, 1)

# 3. REGIONAL COMPARISON
region_avg = df.groupby('region').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
}).reset_index().round(3)
region_avg = region_avg.sort_values('petrol_usd_liter', ascending=False)

# Regional yearly averages for spread
region_yearly = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().reset_index()
region_yearly.columns = ['year', 'region', 'avg_petrol']
region_yearly = region_yearly.round(3)

# Regional spread by year
regional_spread = region_yearly.groupby('year').agg(
    max_petrol=('avg_petrol', 'max'),
    min_petrol=('avg_petrol', 'min')
).reset_index()
regional_spread['spread'] = (regional_spread['max_petrol'] - regional_spread['min_petrol']).round(3)

# 4. SUBSIDY & TAX ANALYSIS
subsidy_avg = df.groupby('subsidy_level').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'tax_percentage': 'mean',
