    'tax_percentage': 'mean',
}).reset_index().round(3)

# Pass-through: correlation of brent with retail, by subsidy level
for sub_level in ['High', 'Low']:
    sub_df = df[df['subsidy_level'] == sub_level]
    corr_val = sub_df['brent_crude_usd'].corr(sub_df['petrol_usd_liter'])
    subsidy_avg.loc[subsidy_avg['subsidy_level'] == sub_level, 'brent_correlation'] = round(corr_val, 3)

# Pass-through by subsidy + income
pass_through = df.groupby(['income_level', 'subsidy_level']).apply(
    lambda x: round(x['brent_crude_usd'].corr(x['petrol_usd_liter']), 3)
).reset_index()
pass_through.columns = ['income_level', 'subsidy_level', 'brent_petrol_corr']

# Subsidy effect during crisis periods
crisis_subsidy = crisis_2022.groupby('subsidy_level').agg({
    'petrol_usd_liter': 'mean',
}).reset_index().round(3)

# Yearly subsidy comparison
yearly_subsidy = df.groupby(['year', 'subsidy_level'])['petrol_usd_liter'].mean().reset_index()
yearly_subsidy = yearly_subsidy.round(3)

# 5. INCOME LEVEL SEGMENTATION
income_avg = df.groupby('income_level').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'tax_percentage': 'mean',
}).reset_index().round(3)

# Price stability by income (CV)
income_stability = df.groupby('income_level').agg({
    'petrol_usd_liter': lambda x: x.std() / x.mean(),
    'diesel_usd_liter': lambda x: x.std() / x.mean(),
}).reset_index()
income_stability.columns = ['income_level', 'petrol_cv', 'diesel_cv']
income_stability = income_stability.round(4)

# Tax-to-price ratio by income level
income_tax = df.groupby('income_level')['tax_percentage'].agg(['mean', 'std', 'min', 'max']).reset_index().round(2)

# Income + region breakdown
income_region = df.groupby(['income_level', 'region']).agg({
    'petrol_usd_liter': 'mean',
    'tax_percentage': 'mean',
}).reset_index().round(3)

# Yearly income trends
yearly_income = df.groupby(['year', 'income_level'])['petrol_usd_liter'].mean().reset_index()
yearly_income = yearly_income.round(3)

# ─── Prepare chart data as JSON ───

# Weekly trend chart data
weekly_chart_data = {
    'dates': weekly_avg['date'].dt.strftime('%Y-%m-%d').tolist(),
    'petrol': weekly_avg['petrol_usd_liter'].round(3).tolist(),
    'diesel': weekly_avg['diesel_usd_liter'].round(3).tolist(),
    'lpg': weekly_avg['lpg_usd_liter'].round(3).tolist(),
    'brent': weekly_avg['brent_crude_usd'].round(2).tolist(),
}

# Yearly volatility chart data
vol_chart_data = {
    'years': yearly_volatility['year'].tolist(),
